<?php
declare(strict_types=1);
namespace Hostider\Support\Mail;
use Hostider\Core\{Id,CanonicalJson,Idempotency,Validation};
use Hostider\Core\Http\HttpError;
use Hostider\Core\Queue\{Outbox,Queue};
use Hostider\Support\{Access,Service};
final readonly class Commands
{
    public function __construct(private Common $m){}
    private function payload(string $action,array $p): array
    {
        $keys=match($action){'review'=>['id','version','decision','proof'],'dispatch'=>['id','version','mode'],'retention'=>['department_id','version','enabled','raw_days','file_days'],'hold'=>['id','version','kind','hold'],default=>throw new HttpError(422,'MAIL_ACTION_INVALID')};Validation::fields($p,$keys,$keys);foreach(['id','department_id'] as $k){if(isset($p[$k])){Access::id($p[$k]);}}\Hostider\Support\Work\Policy::integer($p['version'],$action==='retention'?0:1,2147483647);
        if($action==='review'&&(!in_array($p['decision'],['approve','reject'],true)||!is_string($p['proof'])||strlen($p['proof'])>128)){throw new HttpError(422,'MAIL_DECISION_INVALID');}if($action==='dispatch'&&!in_array($p['mode'],['ACCEPTED_BY_TRANSPORT','RETRYABLE_FAILURE','PERMANENT_FAILURE'],true)){throw new HttpError(422,'MAIL_MODE_INVALID');}if($action==='retention'){foreach(['raw_days','file_days'] as $k){\Hostider\Support\Work\Policy::integer($p[$k],1,365);}if(!is_bool($p['enabled'])){throw new HttpError(422,'BOOLEAN_REQUIRED');}}if($action==='hold'&&(!in_array($p['kind'],['RAW','FILE'],true)||!is_bool($p['hold']))){throw new HttpError(422,'MAIL_HOLD_INVALID');}return $p;
    }
    private function record(string $action,array $p,array $u,array $s): array
    {
        $db=$this->m->c->db;if($action==='retention'){(new Access($this->m->c))->management($u,$s);(new Access($this->m->c))->department($p['department_id']);return $db->execute('SELECT * FROM support_mail_retention WHERE department_id=? FOR UPDATE',[$p['department_id']])->fetch()?:['department_id'=>$p['department_id'],'version'=>0];}
        $table=$action==='dispatch'?'support_mail_outbound':($action==='hold'&&$p['kind']==='FILE'?'support_mail_files':'support_mail_inbound');$r=$db->execute('SELECT * FROM '.$table.' WHERE id=?',[$p['id']])->fetch();if(!$r){throw new HttpError(404,'MAIL_NOT_FOUND');}$dep=$r['department_id']??$db->execute('SELECT department_id FROM support_tickets WHERE id=?',[$r['ticket_id']])->fetchColumn();$this->m->reviewer($u,$s,$dep,$r['customer_id']);if($r['ticket_id']!==null){(new Access($this->m->c))->ticket($u,$s,$r['ticket_id'],'support.mail_review');}$locked=$db->execute('SELECT * FROM '.$table.' WHERE id=? FOR UPDATE',[$r['id']])->fetch();if($locked['customer_id']!==$r['customer_id']||($locked['ticket_id']??null)!==($r['ticket_id']??null)){throw new HttpError(409,'MAIL_STATE_CHANGED');}return $locked;
    }
    public function command(string $reference,string $route,array $body,string $key,string $trace): array
    {
        $this->m->gate();Validation::fields($body,['action','payload','confirmation'],['action','payload']);if(!is_string($body['action'])){throw new HttpError(422,'MAIL_ACTION_INVALID');}$action=$body['action'];$p=$this->payload($action,\Hostider\Support\Work\Policy::array($body['payload']));
        $work=function(bool $replay)use($reference,$route,$body,$action,$p,$trace){return $this->m->c->identity->withStepUp($reference,'admin',function($u,$s)use($route,$body,$action,$p,$trace,$replay){
            if(!$replay&&$action==='review'&&$p['decision']==='approve'){$proof=(new Tokens($this->m))->check($p['proof'],'PROOF');$this->m->c->db->execute('SELECT id FROM identity_users WHERE id=? FOR UPDATE NOWAIT',[$proof['actor_id']])->fetch();}
            $r=$this->record($action,$p,$u,$s);if($replay){return [];}
            if((int)$r['version']!==$p['version']){throw new HttpError(409,'MAIL_VERSION_CONFLICT');}$hash=$this->m->hmac(CanonicalJson::encode($p));$state=$this->m->hmac(CanonicalJson::encode($r));
            if($route==='prepare'){$id=Id::uuid();$this->m->c->db->execute('INSERT INTO support_mail_confirmations(id,actor_id,session_id,identity_version,action,payload_hmac,state_hmac,expiry) VALUES (?,?,?,?,?,?,?,?)',[$id,$u['id'],$s['id'],$u['identity_version'],$action,$hash,$state,time()+300]);$this->m->c->identity->confirmationEvent($u['id'],$id,false);$public=$p;unset($public['proof']);return ['id'=>$id,'action'=>$action,'proposed'=>$public,'effect'=>'TEST_ONLY_NO_REAL_MAIL_OR_AV','expires_in'=>300];}
            $a=\Hostider\Support\Work\Policy::array($body['confirmation']??[]);Validation::fields($a,['id','accepted'],['id','accepted']);Access::id($a['id']);$row=$this->m->c->db->execute('SELECT * FROM support_mail_confirmations WHERE id=? FOR UPDATE',[$a['id']])->fetch();if($a['accepted']!==true||!$row||$row['actor_id']!==$u['id']||$row['session_id']!==$s['id']||(int)$row['identity_version']!==(int)$u['identity_version']||$row['action']!==$action||$row['used_at']!==null||(int)$row['expiry']<=time()||!hash_equals($row['payload_hmac'],$hash)||!hash_equals($row['state_hmac'],$state)){throw new HttpError(409,'MAIL_CONFIRMATION_INVALID');}$this->m->c->db->execute('UPDATE support_mail_confirmations SET used_at=UTC_TIMESTAMP(6) WHERE id=?',[$row['id']]);$out=$this->apply($action,$p,$r,$u,$s,$trace);$this->m->c->identity->confirmationEvent($u['id'],$row['id'],true);return $out;
        });};return (new Idempotency($this->m->c->db))->run($reference,'mail:'.$route,$key,['hmac'=>$this->m->hmac(CanonicalJson::encode($body))],fn()=>$work(false),fn()=>$work(true));
    }
    private function apply(string $action,array $p,array $r,array $u,array $s,string $trace): array
    {
        $db=$this->m->c->db;$actor=(new Access($this->m->c))->actor($u,$s);
        if($action==='retention'){$db->execute('INSERT INTO support_mail_retention(department_id,enabled,raw_days,file_days,version) VALUES (?,?,?,?,?) ON DUPLICATE KEY UPDATE enabled=VALUES(enabled),raw_days=VALUES(raw_days),file_days=VALUES(file_days),version=VALUES(version)',[$p['department_id'],(int)$p['enabled'],$p['raw_days'],$p['file_days'],$p['version']+1]);$this->m->event($p['department_id'],'RETENTION_CONFIGURED',$actor,$trace,['version'=>$p['version']+1]);return ['version'=>$p['version']+1];}
        if($action==='hold'){if($r['purged_at']!==null){throw new HttpError(409,'MAIL_ALREADY_PURGED');}$table=$p['kind']==='RAW'?'support_mail_inbound':'support_mail_files';$db->execute('UPDATE '.$table.' SET hold_content=?,version=version+1 WHERE id=?',[(int)$p['hold'],$r['id']]);$this->m->event($r['id'],'CONTENT_HOLD_CHANGED',$actor,$trace,['hold'=>$p['hold']]);return ['id'=>$r['id'],'version'=>$p['version']+1];}
        if($action==='dispatch'){if(!in_array($r['status'],['HELD','RETRYABLE_FAILURE'],true)){throw new HttpError(409,'MAIL_DISPATCH_STATE');}$id=Id::uuid();$n=(int)$r['attempt_count']+1;if($n>5){throw new HttpError(409,'MAIL_ATTEMPT_LIMIT');}$db->execute('INSERT INTO support_mail_dispatches(event_id,delivery_id,attempt_no,mode,actor_id) VALUES (?,?,?,?,?)',[$id,$r['id'],$n,$p['mode'],$u['id']]);$db->execute("UPDATE support_mail_outbound SET status='PENDING',attempt_count=?,version=version+1 WHERE id=?",[$n,$r['id']]);(new Outbox($db,new Queue($db)))->append($id,'support.mail.dispatch',$r['ticket_id'],['event_uuid'=>$id,'delivery_id'=>$r['id']],$trace);$this->m->event($r['id'],'MOCK_DISPATCH_REQUESTED',$actor,$trace,['event_id'=>$id]);return ['id'=>$r['id'],'event_uuid'=>$id,'version'=>$p['version']+1,'status'=>'PENDING'];}
        if($r['status']!=='REVIEW'){throw new HttpError(409,'MAIL_REVIEW_STATE');}if($p['decision']==='reject'){$db->execute("UPDATE support_mail_inbound SET status='REJECTED',version=version+1 WHERE id=?",[$r['id']]);}else{if($r['raw_encrypted']===null){throw new HttpError(410,'MAIL_RAW_PURGED');}$mail=Mime::parse($this->m->crypto->decrypt($r['raw_encrypted'],'mail-raw:'.$r['id']));$proof=(new Tokens($this->m))->check($p['proof'],'PROOF');$this->m->reviewer($u,$s,$r['department_id'],$proof['customer_id']);if($mail['reply_token']!==null){$reply=(new Tokens($this->m))->check($mail['reply_token'],'REPLY');(new Access($this->m->c))->ticket($u,$s,$reply['ticket_id'],'support.mail_review');}(new Inbound($this->m,Factory::files($this->m)))->attach($r['id'],$mail,$p['proof'],$trace);}$this->m->event($r['id'],'REVIEW_DECIDED',$actor,$trace,['decision'=>$p['decision']]);return ['id'=>$r['id'],'version'=>$p['version']+1,'status'=>$p['decision']==='reject'?'REJECTED':'ATTACHED'];
    }
    public function view(string $reference,string $view,array $p,string $trace): array
    {
        $this->m->gate();Validation::fields($p,$view==='settings'?['department_id']:($view==='list'?['department_id','customer_id','offset']:['id']),in_array($view,['list','settings'],true)?['department_id']:['id']);return $this->m->c->identity->withStepUp($reference,'admin',function($u,$s)use($view,$p,$trace){$db=$this->m->c->db;
            if($view==='settings'){(new Access($this->m->c))->management($u,$s);(new Access($this->m->c))->department(Access::id($p['department_id']));$r=$db->execute('SELECT enabled,raw_days,file_days,version FROM support_mail_retention WHERE department_id=?',[$p['department_id']])->fetch();return $r?:['configured'=>false,'version'=>0];}
            if($view==='list'){$dep=Access::id($p['department_id']);$customer=isset($p['customer_id'])?Access::id($p['customer_id']):null;$this->m->reviewer($u,$s,$dep,$customer);$offset=$p['offset']??'0';if(!is_string($offset)||!ctype_digit($offset)||(int)$offset>100000){throw new HttpError(422,'MAIL_OFFSET');}return $db->execute('SELECT id,department_id,status,reason,version,created_at FROM support_mail_inbound WHERE department_id=? AND '.($customer===null?'customer_id IS NULL':'customer_id=?').' ORDER BY id LIMIT 50 OFFSET '.(int)$offset,$customer===null?[$dep]:[$dep,$customer])->fetchAll();}
            $action=$view==='outbound'?'dispatch':'review';$r=$this->record($action,['id'=>Access::id($p['id'])],$u,$s);if($view==='raw'){if($r['raw_encrypted']===null){throw new HttpError(410,'MAIL_RAW_PURGED');}$this->m->event($r['id'],'RAW_REVIEWED',(new Access($this->m->c))->actor($u,$s),$trace);return ['id'=>$r['id'],'raw_base64'=>base64_encode($this->m->crypto->decrypt($r['raw_encrypted'],'mail-raw:'.$r['id']))];}$out=array_intersect_key($r,array_flip($view==='outbound'?['id','ticket_id','message_id','message_ref','status','version','attempt_count']:['id','department_id','status','reason','version','created_at']));if($view==='outbound'){$out+=['transport'=>'MOCK_DB_SINK','delivery_confirmed'=>false];}return $out;
        });
    }
}
